BAD = {"W", "4", "B", "C", "T"}; DEPTH = 25000.0; WIN = 100; Z = 2.0
# CTA/UTP sale conditions that are tape-eligible for VOLUME ONLY: the plans bar them from updating
# consolidated high/low/last. "I" is the odd lot (on 2026-09-03 it was ~60-80% of every symbol's
# morning prints and set the opening-range edge on 4 of 5 spot-checked names, incl. a ONE-SHARE PLTR
# print at 177.4216). They are real executions but not the market's price, so they stay in `trades`
# (volume/rvol must still count them) and are dropped from every PRICE decision below.
NOT_PRICE = {"I", "V", "7", "P", "U", "Z", "H", "M", "N"}
STATE = os.path.join(config.ROOT, "state")

# Match the stream freshness gate; test fixtures must supply recent observations.
