REST_MIN_QUOTES = 20
QUOTE_SIZE_SHARES_START = date(2025, 11, 3)
# 2026-09-15 cost audit: page size is bounded, every page is fetched inside one overall scan
# deadline, and a page that arrives incomplete/invalid fails its symbol loudly. The deadline
# covers the whole scan (all symbols), not a single request.
PAGE_LIMIT = max(100, min(10000, int(config.getenv("ORBS_PAGE_LIMIT", "10000"))))
PAGE_ATTEMPTS = max(1, int(config.getenv("ORBS_PAGE_ATTEMPTS", "3")))
