    ap = argparse.ArgumentParser(); ap.add_argument("--replay"); ap.add_argument("--end", default="09:38"); a = ap.parse_args()
    d = date.fromisoformat(a.replay) if a.replay else datetime.now(ET).date()
    run(d, a.end)
